import React from 'react';
import Breadcrumb from 'react-bootstrap/Breadcrumb';
import { Link } from "react-router-dom";
import Sidebar from '../common/Sidebar';

const Dashboard = () => {
  return (
      <>
      <div className="container">
        <div className="row">
          <div className="col-12">
              <Breadcrumb>
                  <Breadcrumb.Item linkAs={Link} linkProps={{ to: '/' }}>Home</Breadcrumb.Item>
                  <Breadcrumb.Item active>Cart</Breadcrumb.Item>
              </Breadcrumb>

              <h3>Dashboard</h3>
          </div>
        </div>
      </div>

      <div className="container">
        <div className="row">
          <div className="col-md-3">
            <Sidebar />
          </div>
          <div className="col-md-9 d-flex gap-4 flex-wrap db-rightside">
              <div className="card">
                <div className="card-body">
                  <h2>1</h2>
                  <span>Users</span>
                </div>
                <div className="card-footer">
                    <a href=""><strong>View Users</strong></a>
                </div>
              </div>

              <div className="card">
                <div className="card-body">
                  <h2>1</h2>
                  <span>Orders</span>
                </div>
                <div className="card-footer">
                    <a href=""><strong>View Orders</strong></a>
                </div>
              </div>

              <div className="card">
                <div className="card-body">
                  <h2>1</h2>
                  <span>Products</span>
                </div>
                <div className="card-footer">
                    <a href=""><strong>View Products</strong></a>
                </div>
              </div>

              <div className="card">
                <div className="card-body">
                  <h2>1</h2>
                  <span>Categories</span>
                </div>
                <div className="card-footer">
                    <a href="/admin/categories"><strong>View Categories</strong></a>
                </div>
              </div>
          </div>
        </div>
      </div>
      </>
  )
}

export default Dashboard
