import React from 'react';
import { useForm } from 'react-hook-form';
import {apiUrl} from '../common/Http';
import { toast } from 'react-toastify';
import { useNavigate } from 'react-router-dom';
import { useContext } from 'react';
import { AdminAuthContext } from '../context/AdminAuth';

const Login = () => {
    const {
        register,
        handleSubmit,
        formState: { errors },
    } = useForm();

    const navigate = useNavigate();
    const { login } = useContext(AdminAuthContext);
    const onSubmit = async (data) => {
        const result = await fetch(`${apiUrl}/admin/login`, {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify(data),
            
        }).then(res => res.json());

            if (result.status === 200) {
                const adminInfo = {
                    token: result.token,
                    id: result.id,
                    name: result.name,
                };

                login(adminInfo);
                navigate('/admin/dashboard');
            } else {
                toast.error(result.message);
            }
        };

  return (
    <div className="container my-4">
        <div className="row">
            <form onSubmit={handleSubmit(onSubmit)} className='d-flex  justify-content-center'>
                <div className="card shadow border-0 login">
                    <div className="card-body">
                        <h5 className='text-center'>Admin Login</h5>
                        <div className="mb-4">
                            <label htmlFor="" className='form-label'>Email</label>
                            <input {...register ("email",{required:"The email field is required", pattern: {value: /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i, message: "Invalid email address"} })} type="text" className={`form-control ${errors.email && `is-invalid`}`} placeholder='Email'/>
                            {errors.email && <p className='invalid-feedback'>{errors.email?.message}</p>}
                        </div>
                        <div className="mb-4">
                            <label htmlFor="" className='form-label'>Password</label>
                            <input {...register ("password",{required:"The password field is required"})} type="password" className={`form-control ${errors.password && `is-invalid`}`} placeholder='Password'/>
                            {errors.password && <p className='invalid-feedback'>{errors.password?.message}</p>}
                        </div>
                        <button className="btn btn-primary">Login</button>
                    </div>
                </div>
            </form>
        </div>
    </div>
  )
}

export default Login
