import React from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import { Navbar, Nav, Container, NavDropdown, } from 'react-bootstrap';
import Logo from '../src/assets/images/logo.png';
import { Link } from 'react-router-dom';
import Header from './components/common/Header';
import Home from './components/Home';
import Shop from './components/Shop';
import Product from './components/Product';
import Cart from './components/Cart';
import Checkout from './components/Checkout';
import Login from './components/admin/Login';
import { AdminAuthRequire } from './components/admin/AdminAuthRequire';
import { ToastContainer } from 'react-toastify';
import Dashboard from './components/admin/Dashboard';
import {default as ShowCategories} from './components/admin/category/Show';
import {default as CreateCategory} from './components/admin/category/Create';
import {default as EditCategory} from './components/admin/category/Edit';
import {default as ShowBrands} from './components/admin/brand/Show';
import {default as CreateBrands} from './components/admin/brand/Create';
import {default as EditBrand} from './components/admin/brand/Edit';
import {default as ShowProducts} from './components/admin/product/Show';
import {default as CreateProducts} from './components/admin/product/Create';
import {default as EditProducts} from './components/admin/product/Edit';

function App() {
  return (
    <>
    <HashRouter>
        <Header />
        <Routes>
          <Route path='/' element={<Home />} />
          <Route path='/shop' element={<Shop />} />
          <Route path='/product' element={<Product />} />
          <Route path='/cart' element={<Cart />} />
          <Route path='/checkout' element={<Checkout />} />
          <Route path='/admin/login' element={<Login />} />
          <Route path='/admin/dashboard' element={
            <AdminAuthRequire>
              <Dashboard/>
            </AdminAuthRequire>
          }/>
          <Route path='/admin/categories' element={
            <AdminAuthRequire>
              <ShowCategories/>
            </AdminAuthRequire>
          }/>
          <Route path='/admin/categories/create' element={
            <AdminAuthRequire>
              <CreateCategory/>
            </AdminAuthRequire>
          }/>
          <Route path='/admin/categories/edit/:id' element={
            <AdminAuthRequire>
              <EditCategory/>
            </AdminAuthRequire>
          }/>
          <Route path='/admin/brands' element={
            <AdminAuthRequire>
              <ShowBrands/>
            </AdminAuthRequire>
          }/>
          <Route path='/admin/brands/create' element={
            <AdminAuthRequire>
              <CreateBrands/>
            </AdminAuthRequire>
          }/>
          <Route path='/admin/brands/edit/:id' element={
            <AdminAuthRequire>
              <EditBrand/>
            </AdminAuthRequire>
          }/>
          <Route path='/admin/products' element={
            <AdminAuthRequire>
              <ShowProducts/>
            </AdminAuthRequire>
          }/>
          <Route path='/admin/products/create' element={
            <AdminAuthRequire>
              <CreateProducts/>
            </AdminAuthRequire>
          }/>
          <Route path='/admin/products/edit/:id' element={
            <AdminAuthRequire>
              <EditProducts/>
            </AdminAuthRequire>
          }/>
        </Routes>
      </HashRouter>
      <ToastContainer />
    </>
  );
}

export default App;