import React, { useState } from 'react'
import { useForm } from 'react-hook-form';
import Breadcrumb from 'react-bootstrap/Breadcrumb';
import { Link, useNavigate } from "react-router-dom";
import {apiUrl, adminToken} from '../../common/Http';
import Sidebar from '../../common/Sidebar';
import { toast } from 'react-toastify';

const Create = () => {
    const {
            register,
            handleSubmit,
            formState: { errors },
        } = useForm();

    const [disable, setDisable] = useState(false);
    const navigate = useNavigate();
    const saveCategory = async (data) => {
        setDisable(true);
        const res = await fetch(`${apiUrl}/categories`,{
            method: 'POST',
            headers: {
                'content-type':'application/json',
                'Accept':'application/json', 
                'Authorization':`Bearer ${adminToken()}`
            },
            body: JSON.stringify(data)
        }).then(res => res.json())
        .then(result => {
            setDisable(false);
            if (result.status == 200) {
                toast.success(result.message);
                navigate('/admin/categories');
            } else {
                console.log("Something went wrong");
            }
        })
    }

  return (
    <>
      <div className="container py-4">
        <div className="row">
          <div className="col-12">
              <Breadcrumb>
                  <Breadcrumb.Item linkAs={Link} linkProps={{ to: '/' }}>Home</Breadcrumb.Item>
                  <Breadcrumb.Item active>Create Categories</Breadcrumb.Item>
              </Breadcrumb>
          </div>
        </div>
        <div className="row">
            <div className="d-flex justify-content-between">
                <h3>Categories / Create</h3>
                <Link to="/admin/categories" className='btn btn-primary'>Back</Link>
            </div>
        </div>
      </div>

      <div className="container">
        <div className="row">
          <div className="col-md-3">
            <Sidebar />
          </div>
          <div className="col-md-9">
              <form onSubmit={handleSubmit(saveCategory)}>
                <div className="card shadow">
                    <div className="card-body">
                        <div className="mb-3">
                            <label htmlFor="name" className='form-label'>Name</label>
                            <input {...register("name",{required: "The name field is required"})} type="text" className={`form-control ${errors.name && `is-invalid`}`} placeholder='Name'/>
                            {errors.name && <p className='invalid-feedback'>{errors.name?.message}</p>}
                        </div>
                        <div className="mb-3">
                            <label htmlFor="name" className='form-label'>Status</label>
                            <select {...register ("status", {required: "Please select a status"})} className={`form-control ${errors.status && `is-invalid`}`}>
                                <option value="">Select a Status</option>
                                <option value="1">Active</option>
                                <option value="0">Block</option>
                            </select>
                            {errors.status && <p className='invalid-feedback'>{errors.status?.message}</p>}
                        </div>
                    </div>
                </div>
                <button disabled={disable} className='btn btn-primary mt-4'>Create</button>
              </form>
          </div>
        </div>
      </div>
      </>
  )
}

export default Create
